```yaml
name: Assign dependencies label

on:
  pull_request_target:
    types: [opened, reopened]

permissions:
  issues: write

jobs:
  label:
    runs-on: ubuntu-latest
    steps:
      - name: Add dependencies label to bot PRs
        uses: actions/github-script@v7
        with:
          script: |
            const botUsers = ['dependabot[bot]', 'transifex-integration[bot]', 'imgbot[bot]'];
            const author = context.payload.pull_request.user.login;
            if (!botUsers.includes(author)) {
              core.info(`Skipping PR #${context.payload.pull_request.number} by ${author}`);
              return;
            }
            const labelName = ':heavy_check_mark: dependencies';
            // Check if the label is already present
            const { data: existingLabels } = await github.issues.listLabelsOnIssue({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: context.payload.pull_request.number
            });
            const hasLabel = existingLabels.some(l => l.name === labelName);
            if (hasLabel) {
              core.info(`Label "${labelName}" already present on PR #${context.payload.pull_request.number}`);
              return;
            }
            // Add the label
            await github.issues.addLabels({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: context.payload.pull_request.number,
              labels: [labelName]
            });
